import {Game,BOARD,GROUPS,TOKENS,CARDS} from './engine.js';
import {BoardView,CanvasBoardView} from './board-view.js';
import {icon,tokenArt,cityArt} from './ui-art.js';
const $=id=>document.getElementById(id);
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>`֏${Math.round(n*1000).toLocaleString('en-US')}`;
const color=i=>BOARD[i].type==='property'?GROUPS[BOARD[i].group].color:BOARD[i].type==='station'?'#546e5a':'#a99764';
const key='yerevan-monopoly-v1';let game,view,started=false,saved=null,toastTimer,modalKind='',busy=false,tradeDraft=null,modalInvoker=null,purchaseTimer=null;
const on=(id,fn)=>{if($(id))$(id).onclick=fn;};
try{saved=JSON.parse(localStorage.getItem(key));if(!saved||saved.version!==1||!Array.isArray(saved.players)||saved.players.length<2||saved.players.length>4)saved=null;}catch{}
game=new Game(['Player 1','Player 2']);
function toast(msg){$('toast').textContent=msg;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),4400);}
function save(){if(!started)return;try{localStorage.setItem(key,JSON.stringify(game.s));$('save-label').innerHTML=`${icon('check')} Progress saved`;}catch{$('save-label').textContent='Browser storage unavailable — export your save from the menu.';}}
function modal(html,kind='',wide=false,closable=true){
 if($('overlay').hidden)modalInvoker=document.activeElement;const pending=started&&['buy','card','auction','buildingClaims','debt','transfer'].includes(game.s.phase);const mayClose=closable||pending;
 modalKind=kind;$('overlay').hidden=false;$('modal').className=`modal${wide?' wide':''}`;$('modal').innerHTML=`${mayClose?'<button class="close" id="close-modal" aria-label="Close dialog"></button>':''}${html}${pending?`<button class="review-board secondary" id="review-board">${icon('eye')} Review the board <span>Your decision stays pending</span></button>`:''}`;
 const h=$('modal').querySelector('h2');if(h)h.id='modal-title';if($('close-modal'))$('close-modal').innerHTML=icon('close');on('close-modal',closeModal);on('review-board',closeModal);requestAnimationFrame(()=>{$('modal').querySelector('button,input,select,summary')?.focus({preventScroll:true});});
}
function closeModal(){$('overlay').hidden=true;modalKind='';if(modalInvoker?.isConnected)modalInvoker.focus({preventScroll:true});}
function perform(fn,after){try{const owners=game.s.props.map(p=>p.owner),phase=game.s.phase,auction=game.s.auction?{...game.s.auction}:null;fn();save();render();const acquired=game.s.props.map((p,i)=>p.owner!==null&&p.owner!==owners[i]?i:-1).filter(i=>i>=0);if(after)after();else showPhase();if(acquired.length===1&&['buy','auction'].includes(phase)){const i=acquired[0],owner=game.s.players[game.s.props[i].owner];purchaseNotice(i,owner,phase==='auction'?auction?.bid:BOARD[i].price);}}catch(e){toast(e.message);}}
function purchaseNotice(i,owner,price){const banner=$('purchase-banner');banner.hidden=false;banner.style.setProperty('--purchase-color',TOKENS[owner.id].color);banner.innerHTML=`<span class="token" style="--c:${TOKENS[owner.id].color}">${tokenArt(owner.id)}</span><div><small>NEW PROPERTY OWNER</small><strong>${esc(owner.name)} owns ${esc(BOARD[i].name)}</strong><span>${price?`${money(price)} · `:''}Added to ${esc(owner.name)}’s portfolio</span></div><button class="icon-button" id="dismiss-purchase" aria-label="Dismiss purchase confirmation">${icon('close')}</button>`;on('dismiss-purchase',()=>banner.hidden=true);clearTimeout(purchaseTimer);purchaseTimer=setTimeout(()=>banner.hidden=true,9000);}
function highlightPortfolio(id){closeModal();view?.focusOwner?.(id);const filter=$('portfolio-filter');filter.hidden=false;filter.innerHTML=`<span class="portfolio-dot" style="--c:${TOKENS[id].color}"></span> ${esc(game.s.players[id].name)}’s properties <button id="clear-portfolio">Show all ${icon('close')}</button>`;on('clear-portfolio',()=>{filter.hidden=true;view?.focusOwner?.(null);});const first=game.s.props.findIndex(p=>p.owner===id);if(first>=0)previewSpace(first);}
function purchaseDetails(){const i=game.current.pos,b=BOARD[i],p=game.current;const ids=b.type==='property'?game.group(i):BOARD.map((x,j)=>x.type===b.type?j:-1).filter(j=>j>=0);const count=ids.filter(j=>game.s.props[j].owner===p.id).length;return `<div class="purchase-summary"><div><small>BUY PRICE</small><strong>${money(b.price)}</strong></div><div><small>CASH AFTER BUYING</small><strong class="${p.cash<b.price?'shortfall':''}">${money(p.cash-b.price)}</strong></div></div><div class="set-comparison"><span>${b.type==='property'?esc(GROUPS[b.group].name):b.type==='station'?'Metro deeds':'Utilities'} · You own ${count} / ${ids.length}</span><div>${ids.map(j=>{const owner=game.s.props[j].owner;return `<button class="set-deed" data-compare-deed="${j}" style="--set-color:${owner===null?'#647b72':TOKENS[owner].color}"><i></i><span>${esc(BOARD[j].name)}</span><small>${owner===null?'Bank':esc(game.s.players[owner].name)}</small></button>`;}).join('')}</div></div>`;}
function actor(){return game.s.phase==='debt'?game.s.debt.from:game.s.turn;}
function diceMarkup(n){const spots={1:[4],2:[0,8],3:[0,4,8],4:[0,2,6,8],5:[0,2,4,6,8],6:[0,2,3,5,6,8]};return `<span class="die" role="img" aria-label="Dice ${n}">${Array.from({length:9},(_,i)=>`<i class="${spots[n].includes(i)?'show':''}"></i>`).join('')}</span>`;}
function phaseSteps(phase){const k=phase==='roll'?0:phase==='end'||phase==='won'?2:1;return `<div class="phase-steps" aria-label="Turn progress">${['ROLL','EXPLORE','PASS THE DICE'].map((label,i)=>`${i?'<span class="phase-line"></span>':''}<span class="phase-step ${i===k?'active':''}"><i>${i+1}</i>${label}</span>`).join('')}</div>`;}
function render(){
 const s=game.s,p=game.current,a=s.players[actor()];$('round').textContent=started?`ROUND ${String(s.round).padStart(2,'0')}`:'2–4 PLAYERS';$('player-count').textContent=String(s.players.length).padStart(2,'0');$('roster').style.setProperty('--player-count',s.players.length);
 let heading=started?`${esc(p.name)}’s turn`:'The city is yours.',sub=started?`${esc(BOARD[p.pos].name)}`:'Gather your friends. Build your own story.',button='',note='';
 if(!started)button=`<button class="primary" id="start-table">Set up your table ${icon('arrow')}</button>`;
 else if(s.phase==='roll'){
  sub=p.jailed?`In jail · ${p.jailTurns} of 3 attempts used`:s.extra?'Doubles! You get another roll.':sub;
  button=`<button class="primary" id="roll-dice">${icon('dice')} Roll the dice ${icon('arrow')}</button>`;
  if(p.jailed)button+=`<div class="button-row"><button class="secondary" id="pay-jail">Pay ${money(50)}</button>${p.cards.length?'<button class="secondary" id="use-jail-card">Use free jail card</button>':''}</div>`;
  note=p.jailed?'Roll doubles to leave jail, or pay before rolling.':'Your next corner of Yerevan is a roll away.';
 }else if(s.phase==='end'){heading='A turn well played.';button=`<button class="primary" id="end-turn">Pass the dice to ${esc(nextName())} ${icon('arrow')}</button>`;note='You can manage properties or trade before you finish.';}
 else if(s.phase==='buy'){heading='Look around. Then decide.';button=`${purchaseDetails()}<button class="primary" id="quick-buy" ${p.cash<BOARD[p.pos].price?'disabled':''}>${icon('house')} Buy ${esc(BOARD[p.pos].name)} ${icon('arrow')}</button><div class="button-row"><button class="secondary" id="quick-auction">Decline & auction</button><button class="secondary" id="open-action">View title deed</button></div><button class="text-button compare-portfolio" id="compare-owned">${icon('eye')} Highlight my properties on the board</button>`;note='No rush. Inspect any space or player’s portfolio before deciding.';}
 else if(s.phase==='buildingClaims'){heading='The final building.';sub='One building. More than one ambition.';button=`<button class="primary" id="open-action">Review building claims ${icon('arrow')}</button>`;}
 else if(s.phase==='auction'){heading='Going once…';sub=`${esc(BOARD[s.auction.i].name)}`;button=`<button class="primary" id="open-action">Continue auction ${icon('arrow')}</button>`;note='Every active player can bid with their available cash.';}
 else if(s.phase==='card'){heading='A city of surprises.';button=`<button class="primary" id="open-action">Reveal your card ${icon('arrow')}</button>`;}
 else if(s.phase==='debt'){heading=`${esc(a.name)}, payment due.`;sub=`${money(s.debt.amount)} to ${s.debt.to===null?'the bank':esc(s.players[s.debt.to].name)}`;button=`<button class="primary" id="open-action">Resolve this payment ${icon('arrow')}</button>`;note='Sell buildings, mortgage deeds, or negotiate a trade.';}
 else if(s.phase==='transfer'){heading='An inherited mortgage.';button=`<button class="primary" id="open-action">Review this transfer ${icon('arrow')}</button>`;}
 else if(s.phase==='won'){heading='You own the night.';button=`<button class="primary" id="open-action">${icon('crown')} See the winner</button>`;}
 $('turn-panel').innerHTML=`<div class="turn-card">${started?phaseSteps(s.phase):''}<span class="eyebrow">${started?'YOUR NEXT MOVE':'WELCOME TO THE PINK CITY'}</span><h2>${heading}</h2><p class="turn-location">${icon('landmark')} ${sub}</p><div class="roll-summary"><span>LAST ROLL</span><strong>${started?s.dice.join(' + '):'—'}</strong><small>${p.jailed?'In jail':s.extra?'Doubles · roll again':'Dice are on the table'}</small></div>${button}${note?`<div class="turn-sub">${note}</div>`:''}${started?`<div class="turn-identity"><span class="token" style="--c:${TOKENS[p.id].color}">${tokenArt(p.id)}</span><span>${esc(p.name)} · ${money(p.cash)} available</span></div>`:''}</div>`;
 $('roster').innerHTML=s.players.map(pl=>{const deeds=s.props.map((q,i)=>q.owner===pl.id?i:-1).filter(i=>i>=0);return `<div class="player-row ${started&&pl.id===s.turn?'active':''} ${pl.out?'out':''}" style="--player-color:${TOKENS[pl.id].color}" tabindex="0" role="button" data-player="${pl.id}" aria-label="${esc(pl.name)} properties"><span class="token" style="--c:${TOKENS[pl.id].color}">${tokenArt(pl.id)}</span><div class="player-info"><strong>${esc(pl.name)}</strong><small>${pl.out?'BANKRUPT':`${TOKENS[pl.id].name}${pl.jailed?' · In jail':''}`}</small></div><div class="player-money">${money(pl.cash)}<small>${deeds.length} DEED${deeds.length===1?'':'S'}${pl.cards.length?` · ${pl.cards.length} JAIL CARD${pl.cards.length===1?'':'S'}`:''}</small></div><div class="tiny-deeds">${deeds.map(i=>`<i style="background:${color(i)};opacity:${s.props[i].mortgaged?.35:1}"></i>`).join('')}</div></div>`;}).join('');
 $('roster').querySelectorAll('[data-player]').forEach(el=>{el.onclick=()=>started?showProperties(+el.dataset.player):showSetup();el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();el.click();}};});
 $('journal').innerHTML=s.log.map(l=>`<p>${esc(l)}</p>`).join('');const stock=game.stock();$('bank-stock').innerHTML=`<span class="stock-item">${icon('house')} <strong>${stock.houses}</strong> houses</span><span class="stock-item">${icon('hotel')} <strong>${stock.hotels}</strong> hotels</span>`;
 $('manage-btn').disabled=!started||s.phase==='won';$('trade-btn').disabled=!started||!game.canManage(actor());
 on('start-table',showSetup);on('open-action',()=>game.s.phase==='buy'?showDeed(game.current.pos,true):showPhase());on('quick-buy',()=>perform(()=>game.buy()));on('quick-auction',()=>perform(()=>game.beginAuction()));on('compare-owned',()=>highlightPortfolio(game.current.id));$('turn-panel').querySelectorAll('[data-compare-deed]').forEach(el=>el.onclick=()=>selectSpace(Number(el.dataset.compareDeed)));on('roll-dice',()=>{if(busy)return;busy=true;const rollingGame=game;$('roll-dice').disabled=true;document.body.classList.add('rolling');view?.roll();setTimeout(()=>{document.body.classList.remove('rolling');busy=false;if(game===rollingGame&&game.s.phase==='roll')perform(()=>game.roll());},850);});on('end-turn',()=>perform(()=>game.endTurn()));on('pay-jail',()=>perform(()=>game.jailPay()));on('use-jail-card',()=>perform(()=>game.jailCard()));view?.sync(game);previewSpace(started?p.pos:39);
}
function previewSpace(i){
 const b=BOARD[i],p=game.s.props[i],owner=p.owner===null?null:game.s.players[p.owner];const c=b.type==='property'?GROUPS[b.group].color:'#d7b77c';const group=b.type==='property'?GROUPS[b.group].name:b.type==='station'?'Yerevan Metro':b.type==='utility'?'City utilities':'Around the city';
 const status=owner?`Owned by ${owner.name}${p.mortgaged?' · Mortgaged':''}`:b.price?'Available to buy':'Public space';
 let right=b.price?`${b.type==='utility'?'4× / 10× dice':money(p.owner!==null?game.rent(i):b.type==='property'?b.rents[0]:25)}`:i===0?money(200):i===4?money(200):i===38?money(100):'—';
 $('landmark-panel').innerHTML=`<div class="landmark-kicker"><span>EXPLORE THE CITY</span><span>SPACE ${String(i+1).padStart(2,'0')} / 40</span></div><div class="landmark-body"><div class="landmark-title"><span class="landmark-icon" style="--c:${c}">${icon(b.type==='property'?'landmark':b.type==='utility'?(i===28?'water':'utility'):b.type==='luxury'?'tax':b.type)}</span><div><h3>${esc(b.name.replace(' · ԲԱՐԻ ԳԱԼՈՒՍՏ',''))}</h3><small>${esc(group)}</small><span class="inspector-owner" style="--c:${owner?TOKENS[owner.id].color:'#8b9c85'}">${owner?tokenArt(owner.id):icon('bank')}${esc(status)}</span></div></div><p>${esc(b.fact)}</p><div class="landmark-stats"><div><small>${b.price?'DEED VALUE':'SPACE TYPE'}</small><strong>${b.price?money(b.price):esc(b.type==='go'?'Welcome':b.type==='gotojail'?'Go to Jail':b.type==='chest'?'Community':b.type==='chance'?'Chance':b.type==='parking'?'Rest stop':b.type==='jail'?'Just visiting':'Tax')}</strong></div><div><small>${b.price?'CURRENT / BASE RENT':i===0?'START SALARY':i===4||i===38?'AMOUNT DUE':'NO PURCHASE'}</small><strong>${right}</strong></div></div><button class="text-button" id="inspect-deed">${b.price?'View full title deed':'Read space details'} ${icon('chevron')}</button></div>`;on('inspect-deed',()=>selectSpace(i));
}
function nextName(){let n=game.s.turn;do{n=(n+1)%game.s.players.length;}while(game.s.players[n].out);return game.s.players[n].name;}
function showSetup(count=2,names=[]){
 if(typeof count!=='number')count=2;
 modal(`<span class="eyebrow">ԲԱՐԻ ԳԱԼՈՒՍՏ · WELCOME</span><h2>A game night in Yerevan.</h2><p>Buy the streets you love. Trade for the landmarks you want. Build your way from Kond to Republic Square.</p><div class="setup-hero">${cityArt('setup')}<div><strong>One city.<br>A whole evening.</strong><p>Local multiplayer.<br>A classic game with an Armenian soul.</p></div></div><label>How many at the table?</label><div class="count-picker">${[2,3,4].map(n=>`<button id="count-${n}" class="${n===count?'active':''}">${n} players</button>`).join('')}</div><div id="name-fields">${Array.from({length:count},(_,i)=>`<div class="player-input"><span class="token" style="--c:${TOKENS[i].color}">${tokenArt(i)}</span><input id="name-${i}" aria-label="Player ${i+1} name" maxlength="22" value="${esc(names[i]||`Player ${i+1}`)}" placeholder="Player ${i+1}"><small style="min-width:78px;color:#87937c;font-size:.64rem">${TOKENS[i].name}</small></div>`).join('')}</div><button class="primary dark" id="begin-game">Let’s play · Արի խաղանք &nbsp; →</button>${saved&&!started?'<button class="secondary" id="resume-game" style="width:100%;margin-top:9px">Resume your saved game</button>':''}<p class="setup-foot">Each player starts with ${money(1500)}. Highest opening roll goes first.<br>Progress saves automatically in this browser.</p>`, 'setup',false,started);
 [2,3,4].forEach(n=>on(`count-${n}`,()=>showSetup(n,Array.from({length:count},(_,i)=>$(`name-${i}`).value))));
 on('begin-game',()=>{const ns=Array.from({length:count},(_,i)=>$(`name-${i}`).value.trim()||`Player ${i+1}`);game=new Game(ns);started=true;$('portfolio-filter').hidden=true;$('purchase-banner').hidden=true;view?.focusOwner?.(null);$('overlay').hidden=true;save();render();toast(`${game.current.name} won the opening roll and starts.`);});
 on('resume-game',()=>{game=new Game([],Math.random,saved);started=true;$('overlay').hidden=true;render();showPhase();});
}
function showPhase(){
 if(!started)return;
 const s=game.s;if(s.phase==='buy'){closeModal();}else if(s.phase==='card')showCard();else if(s.phase==='auction')showAuction();else if(s.phase==='buildingClaims')showBuildingClaims();else if(s.phase==='debt')showDebt();else if(s.phase==='transfer')showTransfer();else if(s.phase==='won')showWinner();else{$('overlay').hidden=true;modalKind='';}
}
function showDeed(i,buy=false,backId=null){
 const b=BOARD[i],p=game.s.props[i],owner=p.owner===null?null:game.s.players[p.owner];
 if(!b.price){modal(`<span class="eyebrow">SPACE ${i+1} · YEREVAN</span><h2 id="modal-title">${esc(b.name)}</h2><p>${esc(b.fact)}</p><button class="primary dark" id="deed-close">Back to the table</button>`,'space');on('deed-close',closeModal);return;}
 const managed=owner&&game.canManage(owner.id);let rows='';
 if(b.type==='property')rows=[['Base rent',b.rents[0]],['Full color set · no buildings',b.rents[0]*2],['With 1 house',b.rents[1]],['With 2 houses',b.rents[2]],['With 3 houses',b.rents[3]],['With 4 houses',b.rents[4]],['With a hotel',b.rents[5]]].map(([label,val],n)=>`<tr class="${n===(p.houses?p.houses+1:p.owner!==null&&game.ownsGroup(i,p.owner)?1:0)?'current':''}"><td>${label}</td><td>${money(val)}</td></tr>`).join('');
 else if(b.type==='station')rows=[1,2,3,4].map((n,j)=>`<tr><td>${n} metro deed${n>1?'s':''} owned</td><td>${money(25*2**j)}</td></tr>`).join('');
 else rows='<tr><td>One utility owned</td><td>4 × dice × ֏1,000</td></tr><tr><td>Both utilities owned</td><td>10 × dice × ֏1,000</td></tr>';
 let buttons='';if(buy){buttons=`<button class="primary dark" id="buy-deed" ${game.current.cash<b.price?'disabled':''}>Buy for ${money(b.price)}</button><div class="button-row"><button class="secondary" id="auction-deed">Decline & auction</button><button class="secondary" id="raise-cash">Manage assets</button></div>`;}
 else if(managed){buttons=`<div class="button-row">${b.type==='property'?`<button class="secondary" id="build">Build ${p.houses===4?'hotel':'house'}</button><button class="secondary" id="sell-building">Sell building</button>`:''}<button class="secondary" id="mortgage">${p.mortgaged?'Redeem':'Mortgage'}</button></div>${b.type==='property'&&game.group(i).some(j=>game.s.props[j].houses)?'<button class="text-button" id="liquidate-set" style="width:100%;margin-top:8px">Liquidate all buildings in this set at half price</button>':''}`;}
 modal(`<div class="deed-banner" style="--c:${color(i)}"><small>${b.type==='property'?esc(GROUPS[b.group].name.toUpperCase()):b.type==='station'?'YEREVAN METRO · TRANSPORT DEED':'CITY UTILITIES'}</small><h2 id="modal-title">${esc(b.name)}</h2></div><p>${esc(b.fact)}</p><div class="deed-price"><div><small>DEED VALUE</small><br><strong>${money(b.price)}</strong></div><div style="text-align:right"><span class="live-label">${p.mortgaged?'MORTGAGED':owner?`OWNED BY ${esc(owner.name).toUpperCase()}`:'AVAILABLE'}</span>${b.type==='property'?`<p style="margin:7px 0 0">${p.houses===5?'1 hotel':`${p.houses} houses`}</p>`:''}</div></div><table class="rent-table">${rows}</table><div class="deed-detail"><span>Mortgage: ${money(b.price/2)}<br>Redeem: ${money(Math.ceil(b.price*55/100))}</span><span>${b.type==='property'?`House / hotel: ${money(GROUPS[b.group].house)}<br>Sell buildings for half price`:'Mortgaged deeds collect no rent.'}</span></div>${buttons}<button class="text-button" id="back-assets" style="width:100%;margin-top:15px">${backId!==null?'← Back to properties':'Back to the table'}</button>`, 'deed',false,!buy);
 on('buy-deed',()=>perform(()=>game.buy()));on('auction-deed',()=>perform(()=>game.beginAuction()));on('raise-cash',()=>showProperties(game.current.id));on('back-assets',()=>backId!==null?showProperties(backId):closeModal());
 const manage=action=>perform(()=>game.manage(i,action,owner.id),()=>showDeed(i,false,owner.id));on('build',()=>perform(()=>game.requestBuilding(i,owner.id),()=>game.s.phase==='buildingClaims'?showBuildingClaims():showDeed(i,false,owner.id)));on('sell-building',()=>manage('sell'));on('mortgage',()=>manage(p.mortgaged?'redeem':'mortgage'));
 const disable=(id,reason)=>{const el=$(id);if(el&&reason){el.disabled=true;el.title=reason;}};
 if(owner){const g=b.type==='property'?game.group(i):[i],level=p.houses;
  const reason=b.type!=='property'?'':!game.ownsGroup(i,owner.id)?'Own every deed in this color set to build.':g.some(j=>game.s.props[j].mortgaged)?'Redeem all mortgages in this set first.':level>=5?'This deed already has a hotel.':g.some(j=>game.s.props[j].houses<level)?'Build on the less-developed deeds first.':owner.cash<GROUPS[b.group].house?'Not enough cash for this building.':game.s.phase==='debt'?'Settle the current debt before building.':'';
  disable('build',reason);if($('build'))$('build').innerHTML=icon(level===4?'hotel':'house')+` Build ${level===4?'hotel':'house'} · ${money(GROUPS[b.group].house)}`;
  disable('sell-building',!level?'There are no buildings on this deed.':g.some(j=>game.s.props[j].houses>level)?'Sell from the most-developed deed first.':'');
  disable('mortgage',p.mortgaged?(owner.cash<Math.ceil(b.price*55/100)?'Not enough cash to redeem this deed.':game.s.phase==='debt'?'Settle the current debt first.':''):g.some(j=>game.s.props[j].houses)?'Sell all buildings in this set before mortgaging.':'');
  if($('mortgage'))$('mortgage').textContent=`${p.mortgaged?'Redeem':'Mortgage'} · ${money(p.mortgaged?Math.ceil(b.price*55/100):b.price/2)}`;
  if(reason&&$('build'))$('build').closest('.button-row').insertAdjacentHTML('afterend',`<span class="build-hint">${esc(reason)}</span>`);
 }
 on('liquidate-set',()=>{modal(`<span class="eyebrow">SELL BUILDINGS</span><h2 id="modal-title">Liquidate ${esc(GROUPS[b.group].name)}?</h2><p>Return every house and hotel in this color set to the bank for half its purchase price. The deeds remain yours. This also works when there are not enough houses to break down a hotel.</p><button class="primary dark" id="confirm-liquidate">Sell all buildings in this set</button><button class="text-button" id="cancel-liquidate">Cancel</button>`,'confirm');on('confirm-liquidate',()=>manage('liquidate'));on('cancel-liquidate',()=>showDeed(i,false,owner.id));});
}
function showProperties(id=actor()){
 const player=game.s.players[id],deeds=game.s.props.map((p,i)=>p.owner===id?i:-1).filter(i=>i>=0);const manageable=game.canManage(id);
 modal(`<span class="eyebrow">YOUR CORNER OF YEREVAN</span><h2 id="modal-title">${esc(player.name)}’s properties</h2><button class="secondary locate-portfolio" id="locate-portfolio">${icon('eye')} Highlight this portfolio on the board</button><p>Cash: <strong>${money(player.cash)}</strong> · ${deeds.length} deeds · ${player.cards.length} Get Out of Jail Free cards</p><p>${manageable?'Choose a deed to build, sell buildings, or manage a mortgage. Build and sell evenly across each color set.':'View the deeds below. Complete the pending card, auction or transfer before managing assets.'}</p><div class="property-list">${deeds.map(i=>`<button class="property-chip" style="--c:${color(i)}" data-deed="${i}"><strong>${esc(BOARD[i].name)}</strong><small>${game.s.props[i].mortgaged?'Mortgaged':game.s.props[i].houses===5?'Hotel':game.s.props[i].houses?`${game.s.props[i].houses} houses`:`Rent: ${BOARD[i].type==='utility'?'dice-based':money(game.rent(i))}`}</small></button>`).join('')}</div>${!deeds.length?'<p class="empty">Your city story starts with your first deed.</p>':''}<button class="primary dark" id="properties-done">Back to the table</button>`,'properties',true);
 $('modal').querySelectorAll('[data-deed]').forEach(el=>el.onclick=()=>showDeed(+el.dataset.deed,false,id));on('properties-done',closeModal);on('locate-portfolio',()=>highlightPortfolio(id));
}
function showCard(){const c=game.s.pendingCard,card=CARDS[c.deck][c.id];modal(`<span class="eyebrow">${c.deck==='chance'?'CHANCE · ՇԱՆՍ':'COMMUNITY CHEST · ՀԱՄԱՅՆՔ'}</span><div class="card-art">${icon(c.deck==='chance'?'chance':'chest')}</div><h2 id="modal-title" style="text-align:center">${esc(card.title)}</h2><p style="text-align:center;font-size:1rem">${esc(card.text)}</p><p style="text-align:center">For ${esc(game.current.name)}</p><button class="primary dark" id="resolve-card">Continue &nbsp; →</button>`,'card',false,false);on('resolve-card',()=>perform(()=>game.continueCard()));}
function showAuction(){const a=game.s.auction,b=BOARD[a.i],p=game.s.players[a.bidder];modal(`<span class="eyebrow">THE CITY AUCTION HOUSE</span><h2 id="modal-title">${a.kind?`The bank’s last ${a.kind}`:esc(b.name)}</h2><p>${a.kind?`Only eligible claimants may bid. The winner places the ${a.kind} on their selected deed.`:`Everyone may bid, including the player who declined this deed.`} A pass withdraws that player from this auction.</p><div class="auction-meter"><small>CURRENT BID</small><strong>${money(a.bid)}</strong><small>${a.leader===null?'No bids yet':`Held by ${esc(game.s.players[a.leader].name)}`}</small></div><label for="bid-amount">${esc(p.name)}, your bid · cash ${money(p.cash)}</label><input id="bid-amount" type="number" min="${a.bid+1}" step="1" value="${a.bid+1}" aria-describedby="bid-help"><div class="auction-quick-bids">${[5,25,100].map(n=>`<button data-quick-bid="${n}" ${a.bid+n>p.cash?'disabled':''}>+ ${money(n)}</button>`).join('')}</div><p id="bid-help" style="font-size:.68rem">Enter thousands of dram. For example, 25 means ֏25,000.</p><div class="button-row"><button class="primary dark" id="place-bid" style="margin:0">Place bid</button><button class="secondary" id="pass-bid">Pass</button></div><p>Still bidding: ${game.s.players.filter(p=>!p.out&&!a.passed.includes(p.id)&&(!a.placements||a.placements.some(e=>e.id===p.id))).map(p=>esc(p.name)).join(' · ')}</p>`,'auction',false,false);on('place-bid',()=>perform(()=>game.bid(Number($('bid-amount').value))));on('pass-bid',()=>perform(()=>game.pass()));$('modal').querySelectorAll('[data-quick-bid]').forEach(el=>el.onclick=()=>{$('bid-amount').value=a.bid+Number(el.dataset.quickBid);});}
function showBuildingClaims(){const r=game.s.buildRequest;modal(`<span class="eyebrow">A BUILDING SHORTAGE</span><h2 id="modal-title">The last ${r.kind} in the bank.</h2><p>Each eligible player may claim this building. If more than one player wants it, it goes to auction. Choose a legal placement, or leave “No claim”.</p>${r.candidates.map(c=>`<label for="claim-${c.id}">${esc(game.s.players[c.id].name)}</label><select id="claim-${c.id}"><option value="">No claim</option>${c.deeds.map(i=>`<option value="${i}" ${c.id===r.requester&&i===r.requested?'selected':''}>${esc(BOARD[i].name)} · ${money(GROUPS[BOARD[i].group].house)}</option>`).join('')}</select>`).join('')}<button class="primary dark" id="resolve-claims">Resolve claims &nbsp; →</button>`,'building-claims',false,false);on('resolve-claims',()=>{const claims={};r.candidates.forEach(c=>{const v=$(`claim-${c.id}`).value;if(v!=='')claims[c.id]=+v;});perform(()=>game.buildingClaims(claims));});}
function showDebt(){const d=game.s.debt,p=game.s.players[d.from];modal(`<span class="eyebrow">TIME TO BALANCE THE BOOKS</span><h2 id="modal-title">${esc(p.name)}, payment is due.</h2><p>${esc(d.reason||'Payment')} · Owed to ${d.to===null?'the bank':esc(game.s.players[d.to].name)}</p><div class="auction-meter"><small>AMOUNT DUE</small><strong>${money(d.amount)}</strong><small>Cash available: ${money(p.cash)} · Shortfall: ${money(Math.max(0,d.amount-p.cash))}</small></div><p>Raise cash by selling buildings, mortgaging deeds, or making a trade. Bankruptcy is allowed only if your cash and the liquidation value of all your assets cannot cover the debt.</p><div class="button-row"><button class="secondary" id="debt-assets">Manage properties</button><button class="secondary" id="debt-trade">Make a trade</button></div><button class="primary dark" id="settle-debt" ${p.cash<d.amount?'disabled':''}>Pay ${money(d.amount)}</button><button class="text-button danger" id="bankrupt" style="width:100%;margin-top:12px">Declare bankruptcy</button>`,'debt',false,false);on('debt-assets',()=>showProperties(p.id));on('debt-trade',()=>showTrade(p.id));on('settle-debt',()=>perform(()=>game.settleDebt()));on('bankrupt',()=>{modal(`<span class="eyebrow">LEAVE THE GAME</span><h2 id="modal-title">Declare ${esc(p.name)} bankrupt?</h2><p>Your remaining cash, deeds and cards will be handled by the bankruptcy rules. You will be out of this game.</p><button class="primary dark" id="confirm-bankrupt">Confirm bankruptcy</button><button class="text-button" id="cancel-bankrupt">Return to payment</button>`,'confirm',false,false);on('confirm-bankrupt',()=>perform(()=>game.bankrupt()));on('cancel-bankrupt',showDebt);});}
function showTransfer(){const t=game.s.transfer,b=BOARD[t.i],p=game.s.players[t.owner];modal(`<span class="eyebrow">INHERITED MORTGAGE</span><h2 id="modal-title">${esc(b.name)}</h2><p>${esc(p.name)}, this inherited deed is mortgaged. Pay the immediate 10% interest to keep the mortgage, or pay the mortgage plus interest to redeem it now.</p><button class="primary dark" id="transfer-keep">Keep mortgaged · ${money(Math.ceil(b.price*.05))}</button><button class="secondary" id="transfer-redeem" style="width:100%;margin-top:9px">Redeem now · ${money(Math.ceil(b.price*55/100))}</button>`,'transfer',false,false);on('transfer-keep',()=>perform(()=>game.transferMortgage(false)));on('transfer-redeem',()=>perform(()=>game.transferMortgage(true)));}
function showTrade(id=actor(),partner=null,draft=null){
 const others=game.s.players.filter(p=>!p.out&&p.id!==id);partner=partner??others[0]?.id;if(partner===undefined)return;const a=game.s.players[id],b=game.s.players[partner];
 const column=(pl,side)=>{const ids=game.s.props.map((p,i)=>p.owner===pl.id?i:-1).filter(i=>i>=0);return `<div class="trade-col"><strong>${esc(pl.name)} gives</strong><p>Cash: ${money(pl.cash)}</p>${ids.map(i=>{const locked=BOARD[i].type==='property'&&game.group(i).some(j=>game.s.props[j].houses);return `<label class="trade-deed"><input type="checkbox" name="${side}" value="${i}" ${(draft?.[side]||[]).includes(i)?'checked':''} ${locked?'disabled':''}><i style="--c:${color(i)}"></i><span>${esc(BOARD[i].name)}${locked?' · sell set’s buildings first':game.s.props[i].mortgaged?' · mortgaged':''}</span></label>${game.s.props[i].mortgaged?`<select id="mortgage-${i}" aria-label="Mortgage choice for ${esc(BOARD[i].name)}" style="font-size:.68rem;padding:8px;margin-bottom:9px"><option value="keep">Recipient keeps mortgage · ${money(Math.ceil(BOARD[i].price*5/100))}</option><option value="redeem" ${(draft?.redeem||[]).includes(i)?'selected':''}>Recipient redeems now · ${money(Math.ceil(BOARD[i].price*55/100))}</option></select>`:''}`;}).join('')||'<p>No deeds yet.</p>'}<label for="cash-${side}">Cash in thousands of dram</label><input type="number" min="0" step="1" id="cash-${side}" value="${draft?.[`cash${side}`]||0}"><label for="cards-${side}">Get Out of Jail Free cards</label><input type="number" min="0" max="${pl.cards.length}" id="cards-${side}" value="${draft?.[`cards${side}`]||0}"></div>`;};
 modal(`<span class="eyebrow">A GOOD DEAL GOES BOTH WAYS</span><h2 id="modal-title">Make a trade.</h2><label for="trade-partner">${esc(a.name)} is trading with</label><select id="trade-partner">${others.map(p=>`<option value="${p.id}" ${p.id===partner?'selected':''}>${esc(p.name)}</option>`).join('')}</select><p>Deeds, cash and jail cards can be exchanged. For each mortgaged deed, the recipient can redeem it now or pay 10% interest to keep the mortgage. Redeeming later costs the mortgage plus another 10%.</p><div class="trade-grid">${column(a,'A')}${column(b,'B')}</div><button class="primary dark" id="review-trade">Review proposal &nbsp; →</button><button class="text-button" id="cancel-trade">Cancel</button>`,'trade',true);
 on('trade-partner',()=>showTrade(id,Number($('trade-partner').value)));on('cancel-trade',closeModal);
 on('review-trade',()=>{const d={a:id,b:partner,A:[...$('modal').querySelectorAll('input[name="A"]:checked')].map(e=>+e.value),B:[...$('modal').querySelectorAll('input[name="B"]:checked')].map(e=>+e.value),cashA:Number($('cash-A').value),cashB:Number($('cash-B').value),cardsA:Number($('cards-A').value),cardsB:Number($('cards-B').value),redeem:[...$('modal').querySelectorAll('select[id^="mortgage-"]')].filter(e=>e.value==='redeem'&&$('modal').querySelector(`input[type="checkbox"][value="${e.id.slice(9)}"]`)?.checked).map(e=>+e.id.slice(9))};tradeDraft=d;
  const summary=(pl,side)=>`<p><strong>${esc(pl.name)} gives:</strong><br>${d[side].map(i=>esc(BOARD[i].name)).join(', ')||'No deeds'} · ${money(d[`cash${side}`])} · ${d[`cards${side}`]} free jail cards</p>`;
  modal(`<span class="eyebrow">REVIEW TOGETHER</span><h2 id="modal-title">A deal for ${esc(a.name)} & ${esc(b.name)}.</h2><div class="trade-review">${summary(a,'A')}${summary(b,'B')}</div><p>Pass the screen to ${esc(b.name)}. Accept only when both players agree. ${d.redeem.length?`Redeem immediately: ${d.redeem.map(i=>esc(BOARD[i].name)).join(', ')}. `:''}Any mortgage interest or redemption costs are paid by the receiving players.</p><button class="primary dark" id="accept-trade">${esc(b.name)}: accept this trade</button><div class="button-row"><button class="secondary" id="edit-trade">Edit proposal</button><button class="secondary" id="reject-trade">Decline</button></div>`,'trade-review');
  on('accept-trade',()=>perform(()=>{game.trade(d.a,d.b,d.A,d.B,d.cashA,d.cashB,d.cardsA,d.cardsB,d.redeem);tradeDraft=null;toast('Trade complete.');}));on('edit-trade',()=>showTrade(id,partner,d));on('reject-trade',closeModal);
 });
}
function showWinner(){const p=game.s.players.find(p=>!p.out);modal(`<span class="eyebrow">THE PINK CITY HAS A NEW TYCOON</span><div class="winner">${icon('crown')}</div><h2 id="modal-title" style="text-align:center">${esc(p.name)} owns the night.</h2><p style="text-align:center">The last player standing wins.<br>${game.s.round} rounds · ${money(p.cash)} cash · ${game.s.props.filter(x=>x.owner===p.id).length} deeds</p><button class="primary dark" id="play-again">Another night in Yerevan</button><button class="secondary" id="winner-menu" style="width:100%;margin-top:10px">Export save / game menu</button>`,'winner',false,false);on('play-again',()=>showSetup(game.s.players.length,game.s.players.map(p=>p.name)));on('winner-menu',showMenu);}
function showRules(){modal(`<span class="eyebrow">THE TABLE’S HANDBOOK</span><h2 id="modal-title">Classic rules. A Yerevan soul.</h2><p>Modern classic rules with fixed income tax. All prices and rents use the classic board’s balance, multiplied by 1,000 and displayed as Armenian dram. The landmarks, metro deeds and stories are a local theme; this is an unofficial fan-made edition.</p><div class="rules">
 <details open><summary>01 · Set up & win</summary><p>2–4 people play in turn on one computer. Each starts with ${money(1500)}. Opening rolls select the first player; play proceeds in seat order. Be the last player left after everyone else goes bankrupt. There is no turn limit. Use the 3D / Top view buttons and zoom controls; click any space for its deed.</p></details>
 <details><summary>02 · Turns, START & doubles</summary><p>Roll two dice, move clockwise and resolve the space. Passing or landing on START earns ${money(200)}. Doubles give another roll after you resolve the space. Three consecutive doubles send you directly to jail. Passing the dice ends your turn. The bank handles all cash automatically and has unlimited money.</p></details>
 <details><summary>03 · Buying & auctions</summary><p>Buy an unowned deed at its printed price, or decline and auction it. All active players may bid, including the player who declined. Bids use available cash and must increase by at least ${money(1)}. In this computer auction, pressing Pass withdraws from that auction. The last bidder wins; if everyone passes without bidding, the bank keeps it. There are 22 streets, four metro deeds (the railroad rules), and two utilities.</p></details>
 <details><summary>04 · Rent, metro & utilities</summary><p>Rent is collected automatically on landing. Mortgaged deeds collect no rent. Owning an entire color set doubles its unimproved street rent, even if a sister deed is mortgaged. The four metro deeds charge ${money(25)}, ${money(50)}, ${money(100)} or ${money(200)} with one, two, three or four owned. A utility costs 4× the dice total with one owned, or 10× with both. Special Chance cards apply their stated metro / utility rent. Players in jail still collect rent.</p></details>
 <details><summary>05 · Houses, hotels & the bank supply</summary><p>Own all deeds in a color set and clear all its mortgages to build. Use My properties or click a player. Build evenly: no deed may be more than one level ahead of its set. Four houses may be exchanged for one hotel by paying one additional building cost. The bank has 32 houses and 12 hotels; you cannot buy unavailable stock. Buildings sell back at half price, evenly. A hotel sells back into four houses if stock allows; “Liquidate set” returns every building in the whole set for half price when you need to sell the set together. If multiple players want the bank’s last house or hotel, eligible players choose placements and auction it. Building is available between resolved actions, including other players’ turns through their property panels.</p></details>
 <details><summary>06 · Mortgages & trading</summary><p>Sell all buildings in the color set before mortgaging or trading a street. Mortgage a deed for half its purchase price; redeem at the mortgage amount plus 10%, rounded up to the next game unit. Exchange deeds, cash or Get Out of Jail Free cards via Make a trade, then have the other player accept. The recipient of a mortgaged deed chooses between redeeming immediately at mortgage + 10%, or keeping the mortgage and paying 10% interest immediately. Keeping that mortgage requires paying another 10% when redeeming later. No player loans, IOUs or rent immunity deals are allowed.</p></details>
 <details><summary>07 · Jail & leaving jail</summary><p>Go to Jail, a jail card, or a third consecutive double sends you straight to jail without a START salary and ends your turn. On each of your next three turns, try to roll doubles. Doubles release you and move you by that roll, with no extra roll. Before rolling you may instead pay ${money(50)} or use a free jail card. On a third failed roll you must pay ${money(50)}, leave, and move by the dice. If you cannot pay, resolve the debt first. Landing on the jail space normally is just visiting.</p></details>
 <details><summary>08 · Chance, Chest, taxes & parking</summary><p>Each shuffled deck has 16 cards. Resolve a drawn card and put it at the bottom; free jail cards are held until used or traded. Card movement can trigger another card or a property action. Repairs count each hotel as one hotel, not four houses. Income tax is ${money(200)}; luxury tax is ${money(100)}. Free Parking gives no money or jackpot. Money paid to the bank stays in the bank.</p></details>
 <details><summary>09 · Debt & bankruptcy</summary><p>A payment pauses play if cash is short. The debtor may sell buildings, mortgage deeds and negotiate trades. If liquidation can pay the debt, raise the money and pay it. If it cannot, declare bankruptcy. When owing a player, sell buildings back at half price and transfer cash, deeds and free jail cards to that player; inherited mortgages require an immediate interest or redemption choice. When owing the bank, return jail cards, cancel mortgages and auction the deeds. Eliminated players leave the game; the last remaining player wins.</p></details>
 <details><summary>10 · Saving & the local edition</summary><p>The game saves after actions in this browser. Use the menu to export or import a JSON save. A new game replaces the browser save only after you start it. This is a local pass-and-play game without online accounts or computer opponents. The landmarks are theme choices, not actual properties for sale or a travel map.</p></details>
 </div><p style="font-size:.68rem">Rules reference: <a href="https://instructions.hasbro.com/en-us/instruction/monopoly-board-game-classic-game-with-storage-tray-and-larger-tokens-family-games-8" target="_blank" rel="noopener">Hasbro’s classic game instructions ↗</a></p><button class="primary dark" id="rules-done">Back to the table</button>`,'rules',true);on('rules-done',()=>started?closeModal():showSetup());}
function showMenu(){modal(`<span class="eyebrow">YOUR GAME NIGHT</span><h2 id="modal-title">Take your time.</h2><p>Games save automatically on this browser. Export a save to keep a copy or continue on another computer.</p>${started?'<button class="primary dark" id="export-save">Export game save</button>':''}<button class="secondary" id="import-save" style="width:100%;margin-top:10px">Import game save</button><input type="file" accept=".json,application/json" id="save-file" hidden><button class="secondary" id="menu-rules" style="width:100%;margin-top:10px">Read the rules</button><button class="secondary" id="new-game" style="width:100%;margin-top:10px">Set up a new game</button><button class="text-button" id="menu-close" style="width:100%;margin-top:12px">Back to the table</button>`,'menu');
 on('export-save',()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(game.s,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='yerevan-monopoly-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Save exported.');});
 on('import-save',()=>$('save-file').click());$('save-file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>1000000)throw Error('Save file is too large.');const s=JSON.parse(await f.text());validateSave(s);game=new Game([],Math.random,s);started=true;save();render();showPhase();toast('Game restored.');}catch(err){toast(`Could not import: ${err.message}`);}};
 on('new-game',()=>{if(!started){showSetup();return;}modal(`<span class="eyebrow">A FRESH START</span><h2 id="modal-title">Start another game?</h2><p>Your current browser save will be replaced when the new game begins. Export it first if you want to keep it.</p><button class="primary dark" id="confirm-new">Set up new table</button><button class="text-button" id="cancel-new">Return to current game</button>`,'confirm');on('confirm-new',()=>showSetup(game.s.players.length,game.s.players.map(p=>p.name)));on('cancel-new',closeModal);});on('menu-rules',showRules);on('menu-close',()=>started?closeModal():showSetup());
}
function validateSave(s){if(s?.version!==1||!Array.isArray(s.players)||s.players.length<2||s.players.length>4||!Array.isArray(s.props)||s.props.length!==40||!Number.isInteger(s.turn)||s.turn<0||s.turn>=s.players.length||!['roll','end','buy','auction','buildingClaims','card','debt','transfer','won'].includes(s.phase)||!Array.isArray(s.queue)||!s.decks||!Array.isArray(s.log))throw Error('This is not a valid Yerevan Monopoly save.');for(const [i,p] of s.players.entries())if(p.id!==i||typeof p.name!=='string'||!Number.isFinite(p.cash)||p.cash<0||!Number.isInteger(p.pos)||p.pos<0||p.pos>39||!Array.isArray(p.cards))throw Error('Invalid player data.');for(const p of s.props)if(!(p.owner===null||Number.isInteger(p.owner)&&p.owner>=0&&p.owner<s.players.length)||!Number.isInteger(p.houses)||p.houses<0||p.houses>5)throw Error('Invalid property data.');for(const d of ['chance','chest'])if(!Array.isArray(s.decks[d])||s.decks[d].some(i=>!Number.isInteger(i)||i<0||i>15))throw Error('Invalid card deck.');if(s.phase==='auction'&&!s.auction||s.phase==='debt'&&!s.debt||s.phase==='card'&&!s.pendingCard||s.phase==='transfer'&&!s.transfer)throw Error('Missing action data.');}
on('rules-btn',showRules);on('settings-btn',showMenu);on('manage-btn',()=>showProperties());on('trade-btn',()=>showTrade());on('tab-players',()=>{$('roster').hidden=false;$('roster').style.display='';$('journal').hidden=true;$('tab-players').classList.add('active');$('tab-log').classList.remove('active');});on('tab-log',()=>{$('roster').hidden=true;$('roster').style.display='none';$('journal').hidden=false;$('tab-log').classList.add('active');$('tab-players').classList.remove('active');});
on('view-3d',()=>{view?.setView('3d');$('view-3d').classList.add('active');$('view-top').classList.remove('active');});on('view-top',()=>{view?.setView('top');$('view-top').classList.add('active');$('view-3d').classList.remove('active');});on('rotate-left',()=>view?.rotate?.(-Math.PI/8));on('rotate-right',()=>view?.rotate?.(Math.PI/8));on('zoom-out',()=>view?.setZoom(-.1));on('zoom-in',()=>view?.setZoom(.1));on('reset-view',()=>{if(view){view.zoom=1;const mode=$('view-3d').disabled?'top':'3d';view.setView(mode);$('view-3d').classList.toggle('active',mode==='3d');$('view-top').classList.toggle('active',mode==='top');}});
$('overlay').addEventListener('click',e=>{if(e.target===$('overlay')&&$('close-modal'))closeModal();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('close-modal'))closeModal();if(e.key==='Tab'&&!$('overlay').hidden){const els=[...$('modal').querySelectorAll('button:not(:disabled),input:not([hidden]):not(:disabled),select,summary,a')].filter(el=>el.offsetParent!==null);if(!els.length)return;const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault();}}});
const selectSpace=i=>showDeed(i,started&&game.s.phase==='buy'&&game.current.pos===i);
try{view=new BoardView($('scene'),selectSpace,previewSpace);}catch(e){view=new CanvasBoardView($('scene'),selectSpace,previewSpace);$('view-3d').classList.remove('active');$('view-3d').disabled=true;$('view-3d').title='WebGL is unavailable in this browser';$('view-top').classList.add('active');console.info('Using the canvas top-view fallback because WebGL is unavailable.');}
document.querySelectorAll('[data-icon]').forEach(el=>el.insertAdjacentHTML('afterbegin',icon(el.dataset.icon)));
$('bank-title').innerHTML=icon('bank')+' THE BANK';
let graphicsQuality='ultra';try{graphicsQuality=localStorage.getItem('yerevan-graphics')||'ultra';}catch{}
function setGraphics(q){graphicsQuality=q;view?.setQuality?.(q);$('quality-btn').innerHTML=q==='ultra'?'ULTRA <span>·</span> HiDPI':'BALANCED <span>·</span> HiDPI';$('render-label').textContent=`${q==='ultra'?'ULTRA':'BALANCED'} · ${view instanceof CanvasBoardView?'CRISP TOP VIEW':view?.renderer?.isSoftwareRenderer?'3D TABLE':'3D TABLE'}`;try{localStorage.setItem('yerevan-graphics',q);}catch{}}
